R2 = ["red", "red", "blue", "green"]


def on_bracelet(seq):
    """Is seq read round the repeating bracelet R2, from some starting bead?"""
    return any(all(R2[(st + i) % 4] == c for i, c in enumerate(seq)) for st in range(4))


